class Type12(StrEnum):
    """
    The metering/aggregation method for this plan element, determining how metric values are counted, summed, or analyzed for billing. This is the plan element's `type` field and is distinct from a rating aggregation's `aggregationType` field. COUNT_DISTINCT_VALUE_BY_NAME and DISTINCT_VALUE_BY_NAME are valid here but are not valid `aggregationType` values.
    """

    DISTINCT_VALUE_BY_NAME = 'DISTINCT_VALUE_BY_NAME'
    COUNT_DISTINCT_VALUE_BY_NAME = 'COUNT_DISTINCT_VALUE_BY_NAME'
    SUM = 'SUM'
    COUNT = 'COUNT'
    MAXIMUM = 'MAXIMUM'
    AVERAGE = 'AVERAGE'
    UNIQUE = 'UNIQUE'


class PlanElement(BaseModel):
    """
    Metering element within a pricing plan that defines what is measured and how it is charged. Plan elements specify the metric being tracked, the pricing model (flat rate, per-unit, or tiered), and any specific values to filter on
    """

    distinctValue: Optional[str] = Field(
        None,
        description="Optional filter value to charge only for specific metric values. For example, if measuring by country, this could be 'FRANCE' to charge only for French traffic. Case insensitive",
        examples=['premium'],
    )
    elementDefinitionId: str = Field(
        ...,
        description='The unique identifier of the element definition that specifies what metric is being measured (e.g., API calls, data transfer, compute time)',
        examples=['sBcTTs3'],
    )
    flatAmount: Optional[float] = Field(
        None,
        description='Fixed charge amount applied regardless of usage volume. Used for flat-rate pricing models. Mutually exclusive with unitAmount in most pricing strategies',
        examples=[99.99],
    )
    name: str = Field(
        ...,
        description='The name of the metering element for identification purposes',
        examples=['Shipping Weight'],
    )
    type: Type12 = Field(
        ...,
        description="The metering/aggregation method for this plan element, determining how metric values are counted, summed, or analyzed for billing. This is the plan element's `type` field and is distinct from a rating aggregation's `aggregationType` field. COUNT_DISTINCT_VALUE_BY_NAME and DISTINCT_VALUE_BY_NAME are valid here but are not valid `aggregationType` values.",
        examples=['COUNT'],
    )
    unitAmount: Optional[float] = Field(
        None,
        description='Per-unit charge amount applied to each measured unit. For example, $0.01 per API call or $0.05 per GB transferred. Used for usage-based pricing models',
        examples=[0.01],
    )


