class PrHealthDepartmentNodeRead(BaseModel):
    id: Optional[int] = None
    name: Optional[str] = None


class PrHealthSettingsResource(BaseModel):
    """
    Team-level PR Health configuration settings
    """

    agingDays: int = Field(
        ...,
        description='Days without activity before an open PR counts as aging. Must be lower than rottingDays.',
        examples=[14],
    )
    assistedOnly: Optional[bool] = Field(
        None,
        description="The team's default for pricing and listing AI-assisted pull requests only. True when never set.",
        examples=[True],
    )
    automationPatterns: Optional[list[str]] = Field(
        None,
        description="Custom regular expressions (PostgreSQL syntax, case-insensitive) matched against a pull request's title and author login; a match puts the pull request in the automation bucket. An empty list on write clears them. At most 20, each at most 200 characters, and none may match an empty string.",
    )
    builtInAutomationPatterns: Optional[list[str]] = Field(
        None,
        description='The built-in automation patterns (Snyk, Dependabot, Renovate) applied beside the custom ones. Declared bot authors always count as automation too.',
    )
    cutoffDate: Optional[date_aliased] = Field(
        None,
        description="The team's own cutoff: pull requests opened before this UTC date are left out of every PR Health figure, counts and dollar estimates alike. Null on read when the team has not set one: counts then cover the whole synced git history, and dollar estimates start at defaultCutoffDate. On write, a custom date between 2008-01-01 and today UTC; absent or null leaves the stored date unchanged.",
        examples=['2025-03-01'],
    )
    cutoffDateIsDefault: Optional[bool] = Field(
        None,
        description="False when cutoffDate is the team's own date; true when the team has none and the default applies (counts over full history, dollar estimates from defaultCutoffDate); null when the team has no date and the organization no coding-assistant usage. On write, true clears the custom date and restores the default, and any cutoffDate in the same body is ignored.",
        examples=[True],
    )
    defaultCutoffDate: Optional[date_aliased] = Field(
        None,
        description="The organization's first coding-assistant day (metering start): without a team cutoffDate, dollar estimates leave out pull requests opened before it, while counts do not. Returned even while a custom cutoffDate overrides it; null when the organization has no coding-assistant usage.",
        examples=['2025-02-14'],
    )
    excludedRepos: Optional[list[str]] = Field(
        None,
        description='Repositories (owner/name) left out of every PR Health figure, matched case-insensitively. Returned sorted; an empty list on write clears them. At most 200.',
    )
    rottingDays: int = Field(
        ...,
        description='Days without activity before an open PR counts as rotting. Must be higher than agingDays.',
        examples=[30],
    )


