    contains: Optional[str] = Field(
        None,
        description='Substring pattern to match against the source URL or path. If the source contains this string anywhere, the classification rule matches',
        examples=['/internal/'],
    )
    endsWith: Optional[str] = Field(
        None,
        description='Suffix pattern to match against the source URL or path. If the source ends with this string, the classification rule matches',
        examples=['/health'],
    )
    equalsTo: Optional[str] = Field(
        None,
        description='Exact match pattern for the source URL or path. The source must exactly match this string for the classification rule to apply',
        examples=['/api/v2/products'],
    )
    regex: Optional[str] = Field(
        None,
        description='Regular expression pattern to match against the source URL or path. Provides flexible pattern matching for complex classification rules',
        examples=['^/api/v[0-9]+/users/.*$'],
    )


