class RatingAggregation(BaseModel):
    """
    Usage-based pricing configuration that defines how metered data is aggregated and billed. Rating aggregations enable complex pricing models by specifying what metric to measure, how to calculate it, and what pricing tiers to apply based on usage levels
    """

    aggregationType: AggregationType = Field(
        ...,
        description="The method used to calculate the aggregated value from the metered data. To count distinct values (for example, unique regions or customer IDs), use DISTINCT. This is separate from a plan element's `type` field: values like COUNT_DISTINCT_VALUE_BY_NAME and DISTINCT_VALUE_BY_NAME belong to the plan element `type` field, not to aggregationType.",
        examples=['SUM'],
    )
    distinctValue: Optional[str] = Field(
        None,
        description="Optional filter value for distinct-value-based aggregations. When specified, only metrics matching this value (case insensitive) are included in the aggregation. For example, 'FRANCE' to aggregate only transactions where the metering element was sent with the value 'FRANCE' to aggregate French transactions.",
        examples=['PREMIUM'],
    )
    elementDefinitionId: str = Field(
        ...,
        description='The identifier of the element definition that specifies which metric to aggregate. References an ElementDefinition that defines the data field to measure',
        examples=['3By6OgB'],
    )
    graduated: Optional[bool] = Field(
        None,
        description="Determines the tier pricing model. When true, uses graduated pricing where each tier's rate applies only to usage within that tier's range. When false, uses volume pricing where the entire usage is charged at the rate of the highest tier reached",
        examples=[True],
    )
    id: Optional[str] = Field(
        None,
        description='The unique identifier of the rating aggregation',
        examples=['l3kR6l'],
    )
    name: str = Field(
        ...,
        description='The name of the rating aggregation for identification and display purposes',
        examples=['API Calls by Region'],
    )
    tiers: Optional[list[TierModel]] = Field(
        None,
        description='Volume-based pricing tiers that define different rates based on usage levels. Each tier specifies a usage range and corresponding pricing.',
    )


