class Plan(BaseModel):
    """
    Product pricing plan configuration defining billing structure, pricing tiers, metering elements, and subscription terms. Plans support recurring subscriptions with optional trial periods and metered usage
    """

    charge: Optional[float] = Field(
        None,
        description='The fixed recurring charge amount for subscription plans. This is the base subscription fee charged each billing period',
        examples=[99.99],
    )
    currency: Currency6 = Field(
        ...,
        description='The currency code for all pricing in this plan',
        examples=['USD'],
    )
    elements: Optional[list[PlanElement]] = Field(
        None,
        description='Metering elements that define what is being measured and billed in this plan. Each element specifies a metric, unit price, and optional quotas',
    )
    graduated: Optional[bool] = Field(
        None,
        description="Indicates whether volume pricing tiers are graduated (cumulative) or not. When true, each tier applies only to usage within that tier's range. When false, the entire usage is charged at the rate of the highest tier reached",
        examples=[True],
    )
    name: str = Field(
        ...,
        description='The name of the plan for identification and display purposes',
        examples=['Professional Plan'],
    )
    period: Optional[Period] = Field(
        None,
        description='The billing period unit. Defines the recurring billing cycle (e.g., MONTH for monthly billing). Valid values: DAY, MONTH, YEAR, TEST_MINUTE, TEST_MINUTE_WITH_SYNTHETIC_METERING, NONE. NONE means the plan has no recurring billing cycle: Revenium does not invoice it on a schedule, and a subscription to it cannot be given a future start date. TEST_MINUTE and TEST_MINUTE_WITH_SYNTHETIC_METERING are test periods that run billing on a one-minute cycle so you can check how your bills calculate without waiting for a real period.',
        examples=['MONTH'],
    )
    periodCount: Optional[int] = Field(
        None,
        description='The number of period units between billing cycles. For example, 3 with period=MONTH means billing every 3 months. Must be a positive integer (e.g., 1, 3, 12)',
        examples=[1],
    )
    prePayAllFlatRates: Optional[bool] = Field(
        None,
        description='Indicates whether subscription flat rate charges should be paid upfront at subscription creation rather than at the end of the first billing period',
        examples=[False],
    )
    ratingAggregations: Optional[list[RatingAggregation]] = Field(
        None,
        description='Usage aggregation rules that define how metered usage is grouped and calculated for billing purposes. Includes quota limits and overage handling',
    )
    setupFees: Optional[list[SetupFee]] = Field(
        None,
        description='One-time setup fees charged when a subscription is created. Each setup fee has a name, amount, and type',
    )
    tiers: Optional[list[TierModel]] = Field(
        None,
        description='Volume-based pricing tiers that define different rates based on usage levels. Each tier specifies a usage range and corresponding pricing',
    )
    trialPeriod: Optional[TrialPeriod] = Field(
        None,
        description='The trial period unit for subscription plans. TEST_MINUTE and TEST_MINUTE_WITH_SYNTHETIC_METERING are test periods that run billing on a one-minute cycle so you can check how your bills calculate without waiting for a real period.',
        examples=['DAY'],
    )
    trialPeriodCount: Optional[int] = Field(
        None,
        description='The number of trial period units before billing begins. For example, 14 with trialPeriod DAY means a 14-day free trial',
        examples=[14],
    )
    type: Type11 = Field(
        ...,
        description='The plan type determining the billing model. SUBSCRIPTION represents recurring billing with optional metered usage.',
        examples=['SUBSCRIPTION'],
    )


